-- Read-only catalog queries. No user data, secrets, sequence current values or scheduler commands.
select jsonb_build_object('functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'definition',pg_get_functiondef(p.oid)) order by p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f'),'sequences',(select jsonb_agg(jsonb_build_object('name',sequencename,'owner',sequenceowner,'type',data_type,'start',start_value,'min',min_value,'max',max_value,'increment',increment_by,'cycle',cycle,'cache',cache_size)) from pg_sequences where schemaname='public'),'auth_triggers',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='auth' and not t.tgisinternal),'events',(select jsonb_agg(jsonb_build_object('name',evtname,'event',evtevent,'enabled',evtenabled,'function',evtfoid::regproc::text,'tags',evttags)) from pg_event_trigger),'default_acl',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'type',d.defaclobjtype,'acl',d.defaclacl)) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname='public' or d.defaclnamespace=0),'public_schema',(select jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',nspacl) from pg_namespace where nspname='public'),'publications',(select jsonb_agg(jsonb_build_object('publication',pubname,'schema',schemaname,'table',tablename)) from pg_publication_tables where schemaname='public')) as snapshot;

-- This second query casts bigint sequence bounds to text to preserve precision in JSON consumers.
select jsonb_build_object('functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'definition',pg_get_functiondef(p.oid))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname like 'spodora%' and p.prokind='f'),'relations',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname like 'spodora%' and c.relkind in ('r','v','m','S')),'schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl)) from pg_namespace where nspname like 'spodora%'),'sequences',(select jsonb_agg(jsonb_build_object('name',sequencename,'type',data_type,'start',start_value::text,'min',min_value::text,'max',max_value::text,'increment',increment_by::text,'cycle',cycle,'cache',cache_size::text)) from pg_sequences where schemaname='public')) as snapshot;
